#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Source-executed WAV import integrity controls: temporary real RIFF files, no MIDI.

Default: tools/sampleio.py in the repository checkout. For isolated source-window
preflight pass an explicit source filename; that is NOT complete-root qualification.
"""
import importlib.util
import math
import pathlib
import struct
import sys
import tempfile
import unittest

ROOT = pathlib.Path(__file__).resolve().parents[2]
SOURCE = pathlib.Path(sys.argv.pop(1)) if len(sys.argv) > 1 else ROOT / 'tools/sampleio.py'
spec = importlib.util.spec_from_file_location('wav_import_under_test', SOURCE)
assert spec and spec.loader
sio = importlib.util.module_from_spec(spec)
spec.loader.exec_module(sio)


def riff(chunks):
    body = b'WAVE' + b''.join(k + struct.pack('<I', len(v)) + v + (b'\0' if len(v) & 1 else b'') for k, v in chunks)
    return b'RIFF' + struct.pack('<I', len(body)) + body


def fmt(tag=1, bits=16, channels=1, rate=22050, align=None):
    bps = bits // 8
    if align is None:
        align = channels * bps
    return struct.pack('<HHIIHH', tag, channels, rate, rate * align, align, bits)


def extensible(tag=1, bits=24, channels=2, valid=None, cbsize=22, guid=None):
    if valid is None:
        valid = bits
    if guid is None:
        guid = struct.pack('<I', tag) + bytes.fromhex('00001000800000aa00389b71')
    return fmt(0xfffe, bits, channels) + struct.pack('<HHI', cbsize, valid, 0) + guid


class WavImportSafety(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='wav-integrity-')
        self.addCleanup(self.temp.cleanup)
        self.file = pathlib.Path(self.temp.name) / 'sample.wav'

    def load(self, format_bytes, samples=b'\x00\x00', extra=()):
        self.file.write_bytes(riff([(b'fmt ', format_bytes), *extra, (b'data', samples)]))
        return sio.read_any_wav(self.file)

    def test_pcm_positive_formats(self):
        cases = [(8, b'\x80\xff', [0.0, 127/128]),
                 (16, struct.pack('<2h', 0, 16384), [0.0, 0.5]),
                 (24, b'\x00\x00\x00\x00\x00\x40', [0.0, 0.5]),
                 (32, struct.pack('<2i', 0, 1073741824), [0.0, 0.5])]
        for bits, data, expected in cases:
            with self.subTest(bits=bits):
                rate, values = self.load(fmt(bits=bits), data)
                self.assertEqual(rate, 22050)
                self.assertEqual(values, expected)

    def test_float_positive_formats(self):
        for bits, code in ((32, 'f'), (64, 'd')):
            with self.subTest(bits=bits):
                rate, values = self.load(fmt(tag=3, bits=bits), struct.pack('<2'+code, 0.25, -0.75))
                self.assertEqual(rate, 22050)
                self.assertEqual(values, [0.25, -0.75])

    def test_extensible_standard_guids_allowed(self):
        self.assertEqual(self.load(extensible(1,16,1), struct.pack('<h',8192))[1], [0.25])
        self.assertEqual(self.load(extensible(3,32,1), struct.pack('<f',0.25))[1], [0.25])

    def test_bad_format_tags_and_depths_rejected(self):
        cases = [fmt(bits=12), fmt(bits=7), fmt(bits=40), fmt(tag=3,bits=16), fmt(tag=3,bits=24), fmt(tag=6,bits=16)]
        for index, f in enumerate(cases):
            with self.subTest(case=index):
                with self.assertRaises(ValueError): self.load(f,b'\0'*12)

    def test_zero_channels_and_rate_rejected(self):
        for f in (fmt(channels=0),fmt(rate=0)):
            with self.assertRaises(ValueError): self.load(f,b'\0'*12)

    def test_bad_or_truncated_fmt_rejected_cleanly(self):
        for f in (b'\x01', b'\0'*15, b'\0'*17):
            with self.assertRaises(ValueError): self.load(f)
        self.file.write_bytes(b'RIFF' + b'\0'*4 + b'WAVE' + b'fmt ' + struct.pack('<I',100) + fmt())
        with self.assertRaises(ValueError): sio.read_any_wav(self.file)

    def test_frame_alignment_rejected(self):
        for align in (1, 3, 5):
            with self.subTest(align=align):
                with self.assertRaises(ValueError): self.load(fmt(bits=16,channels=2,align=align), b'\0'*16)

    def test_extensible_extension_contract_rejected(self):
        cases = [extensible()[:30], extensible(cbsize=8), extensible(valid=0), extensible(valid=32),
                 extensible(guid=bytes.fromhex('0100000000001000800000aa00389b70')),
                 extensible(guid=bytes.fromhex('0100010000001000800000aa00389b71'))]
        for index, f in enumerate(cases):
            with self.subTest(case=index):
                with self.assertRaises(ValueError): self.load(f,b'\0'*16)

    def test_float_payload_nonfinite_rejected(self):
        for bits, code in ((32, 'f'), (64, 'd')):
            for val in (math.nan,math.inf,-math.inf):
                with self.subTest(bits=bits, val=val):
                    with self.assertRaisesRegex(ValueError,'NaN|infinity'):
                        self.load(fmt(tag=3,bits=bits), struct.pack('<'+code,val))

    def test_float64_stereo_mix_overflow_rejected(self):
        with self.assertRaisesRegex(ValueError,'mix overflow'):
            self.load(fmt(tag=3,bits=64,channels=2),struct.pack('<2d',1e308,1e308))

    def test_float64_multichannel_mix_overflow_rejected(self):
        with self.assertRaisesRegex(ValueError,'mix overflow'):
            self.load(fmt(tag=3,bits=64,channels=3),struct.pack('<3d',1e308,1e308,-1e308))

    def test_finite_mix_preserves_order_and_values(self):
        self.assertEqual(self.load(fmt(tag=3,bits=64,channels=2),struct.pack('<2d',0.75,-0.25))[1],[0.25])
        self.assertEqual(self.load(fmt(tag=3,bits=64,channels=3),struct.pack('<3d',0.75,-0.25,0.25))[1],[0.25])

    def test_resampling_overflow_rejected(self):
        with self.assertRaisesRegex(ValueError,'resampling overflow'):
            sio.resample([1e308]*8,44100,22050)

    def test_normal_resampling_unmodified(self):
        self.assertEqual(sio.resample([0.0,0.5,1.0,0.5],22050,22050),[0.0,0.5,1.0,0.5])
        self.assertTrue(all(math.isfinite(v) for v in sio.resample([0.0,0.5,1.0,0.5],44100,22050)))

    def test_truncated_data_allowed(self):
        self.file.write_bytes(riff([(b'fmt ',fmt()),(b'data',struct.pack('<2h',1,2))])[:-1])
        rate,values=sio.read_any_wav(self.file)
        self.assertEqual(rate,22050)
        self.assertEqual(values,[1/32768])


if __name__ == '__main__':
    unittest.main(verbosity=2)

/* SPDX-License-Identifier: GPL-3.0-only */
/* Thin wrapper around the reference 9W9 engine (built from 9W9's own sources by
 * run_drum909.sh, with libm and doubles), so drum909_test.c never includes a
 * reference header and builds under the port's warning flags. */
#include <stdlib.h>
#include "er99_engine.h"

void *ref_new(const char *module_dir)
{
    er99_engine_t *e = (er99_engine_t *)calloc(1, sizeof(er99_engine_t));
    er99_engine_init(e, 44100.0f, module_dir);
    return e;
}

void ref_free(void *e)
{
    er99_engine_free((er99_engine_t *)e);
    free(e);
}

int ref_set(void *e, const char *key, float pot) { return er99_engine_set_param((er99_engine_t *)e, key, pot); }

int ref_get(void *e, const char *key, float *pot) { return er99_engine_get_param((er99_engine_t *)e, key, pot); }

int ref_set_raw(void *e, const char *key, float v) { return er99_engine_set_raw((er99_engine_t *)e, key, v); }

void ref_trigger(void *e, int which, int vel) { er99_engine_trigger((er99_engine_t *)e, (er99_trigger_t)which, vel); }

void ref_render(void *e, float *out, int n) { er99_engine_render((er99_engine_t *)e, out, n); }

/* er99_pot_to_value for a pot key; -1e30 if unknown */
float ref_pot_value(const char *key, int pot)
{
    for (int i = 0; i < ER99_POT_COUNT; ++i)
        if (!strcmp(g_er99_pots[i].key, key))
            return er99_pot_to_value(&g_er99_pots[i], pot);
    return -1e30f;
}

/* the reference noise generator's first n values */
void ref_noise(float *out, int n)
{
    wa_noise_t z;
    wa_noise_init(&z, 0xC0FFEEu);
    for (int i = 0; i < n; ++i)
        out[i] = wa_noise_tick(&z);
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Compare the production packed renderer against the original nibble reader. */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
static void lcd_sync(void) {}
static void lcd_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const uint16_t *p)
{ (void)x; (void)y; (void)w; (void)h; (void)p; }
#include "../../firmware/src/gfx.c"
#include "font_raw.h"

static int32_t raw_text(int32_t x, int32_t y, const felucca_font_t *f, const char *s, uint16_t colour)
{
    uint32_t red = colour >> 11, green = (colour >> 5) & 63u, blue = colour & 31u;
    for (; *s; s++) {
        uint32_t gi = glyph(f, (uint8_t)*s), w = f->bw[gi], stride = (w + 1) / 2, gy, gx;
        const uint8_t *p = f->data + f->off[gi];
        for (gy = 0; gy < f->h; gy++)
            for (gx = 0; gx < w; gx++) {
                uint32_t alpha = p[gy * stride + gx / 2];
                int32_t px = x - f->pad + (int32_t)gx, py = y + (int32_t)gy + cv_oy;
                alpha = gx & 1 ? alpha & 15 : alpha >> 4;
                if (!alpha || (uint32_t)px >= cv_w || py < cv_y0 || py >= cv_y1)
                    continue;
                if (alpha == 15) cv_px[py * cv_w + px] = swap16(colour);
                else {
                    uint32_t bg = swap16(cv_px[py * cv_w + px]);
                    uint32_t r = (red * alpha + (bg >> 11) * (15 - alpha)) / 15;
                    uint32_t g = (green * alpha + ((bg >> 5) & 63) * (15 - alpha)) / 15;
                    uint32_t b = (blue * alpha + (bg & 31) * (15 - alpha)) / 15;
                    cv_px[py * cv_w + px] = swap16((r << 11) | (g << 5) | b);
                }
            }
        x += f->adv[gi];
    }
    return x;
}

int main(void)
{
    static const felucca_font_t *const packed[] = {&FONT_T, &FONT_XS, &FONT_S, &FONT_B, &FONT_M, &FONT_L};
    static const felucca_font_t *const raw[] = {&RAW_FONT_T, &RAW_FONT_XS, &RAW_FONT_S, &RAW_FONT_B, &RAW_FONT_M, &RAW_FONT_L};
    static uint16_t reference[240 * 80];
    uint32_t role, ch, variant, cases = 0;
    for (role = 0; role < sizeof packed / sizeof *packed; role++) {
        const felucca_font_t *f = packed[role], *r = raw[role];
        assert(f->h == r->h && f->pad == r->pad && f->first == r->first && f->last == r->last);
        assert(!memcmp(f->bw, r->bw, f->last - f->first + 1));
        assert(!memcmp(f->adv, r->adv, f->last - f->first + 1));
        for (ch = 1; ch < 256; ch++) {
            char s[4] = {(char)ch, '8', (char)ch, 0};
            /* The number-only L face has no '?' fallback; its callers use its
             * declared range. Other faces also exercise fallback and folding. */
            if ((f->first > '?' || f->last < '?') && (ch < f->first || ch > f->last))
                continue;
            for (variant = 0; variant < 4; variant++) {
                int32_t x = variant == 1 ? -6 : variant == 2 ? 227 : 7;
                int32_t y = variant == 3 ? -9 : 2, end;
                uint16_t bg = variant & 1 ? RGB(71, 125, 218) : RGB(26, 30, 33);
                uint16_t fg = variant & 2 ? RGB(247, 133, 62) : C_WHITE;
                cv_begin(240, 80, bg);
                if (variant == 3) cv_band(3, 13);
                end = raw_text(x, y, r, s, fg);
                memcpy(reference, cv_px, sizeof reference);
                cv_begin(240, 80, bg);
                if (variant == 3) cv_band(3, 13);
                assert(cv_text(x, y, f, s, fg) == end);
                if (memcmp(reference, cv_px, sizeof reference)) {
                    fprintf(stderr, "font role %u character %u variant %u differs\n", role, ch, variant);
                    return 1;
                }
                cases++;
            }
        }
    }
    printf("font packing: %u rendered cases retain identical pixels and metrics\n", cases);
    return 0;
}

/* Execute the production main-loop editor/update block across transfer boundaries. */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>

static struct { unsigned ota_req, uboot_req; } usb;
static struct { unsigned pending; } bootguard;
static uint32_t fm1_ms, ed_reboot_at;
static uint8_t ed_install_pending;
static void ed_install_forget(void) { ed_install_pending = 0; }
static int busy, next_busy, inject_update, flash_ok = 1, seq, pending_ota;
static unsigned reboots, detaches, ota_polls, ota_entries, uboot_entries, stops;
enum { C_BLACK = 0 };

static int ui_project_busy(void) { return busy; }
static int ed_service(void)
{
    if (inject_update)
        usb.ota_req = usb.uboot_req = 1;
    if (next_busy >= 0)
        busy = next_busy;
    return pending_ota;
}
static void usb_detach(void) { detaches++; }
static void fm1_delay_ms(unsigned ms) { assert(ms == 30); }
static void fm1_reboot(void) { reboots++; }
static void ota_service(void) { ota_polls++; }
static void seq_stop(int *s) { assert(s == &seq); stops++; }
static void ota_session(void) { ota_entries++; }
static void lcd_fill(int x, int y, int w, int h, int c)
{
    assert(!x && !y && w == 240 && h == 240 && c == C_BLACK);
}
static void ui_init(void) {}
static void enter_uboot(const char *why) { assert(why); uboot_entries++; }

static void poll(void)
{
    int ota_pending;
#include "project_updates.inc"
}
static void reset(void)
{
    usb.ota_req = usb.uboot_req = 0;
    bootguard.pending = 1;
    fm1_ms = 1000;
    ed_reboot_at = 0;
    busy = inject_update = 0;
    next_busy = -1;
    pending_ota = 1;                                /* the editor peek left a non-editor frame */
    reboots = detaches = ota_polls = ota_entries = uboot_entries = stops = 0;
}

int main(void)
{
    reset();
    busy = 1;
    ed_reboot_at = 1;
    usb.ota_req = usb.uboot_req = 1;
    poll();
    assert(!reboots && !detaches && bootguard.pending && ed_reboot_at == 1);
    assert(!ota_polls && !ota_entries && !uboot_entries && !stops);
    assert(!usb.ota_req && !usb.uboot_req);
    busy = 0;
    poll();
    assert(reboots == 1 && detaches == 1 && !bootguard.pending);
    assert(!ota_entries && !uboot_entries);           /* cleared requests cannot replay */

    reset();
    next_busy = 1;                                  /* BEGIN acquires the hold in ed_service */
    inject_update = 1;
    ed_reboot_at = 1;
    poll();
    assert(busy && !reboots && !ota_polls && !ota_entries && !uboot_entries);
    assert(!usb.ota_req && !usb.uboot_req);

    reset();
    busy = 1;
    next_busy = 0;                                  /* COMMIT / ABORT releases the hold in ed_service */
    inject_update = 1;                              /* interrupt arrives while that handler runs */
    poll();
    assert(!busy && ota_polls == 1 && !ota_entries && !uboot_entries && !stops);
    assert(!usb.ota_req && !usb.uboot_req);

    reset();
    usb.ota_req = 1;
    poll();
    assert(ota_polls == 1 && ota_entries == 1 && stops == 1 && !usb.ota_req);
    reset();
    usb.uboot_req = 1;
    poll();
    assert(uboot_entries == 1);
    reset();
    ed_reboot_at = 800;                              /* retain the diagnostic reply's 200 ms grace */
    poll();
    assert(!reboots);
    fm1_ms++;
    poll();
    assert(reboots == 1);
    reset();
    pending_ota = 0;                                /* no non-editor frame from this editor check */
    poll();
    assert(!ota_polls && !ota_entries && !uboot_entries);
    puts("project_update_guard: held restart, BEGIN/COMMIT update discard and idle updates ok");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Host test of the pad calibration logic (app/smk_padcal.h, BEHAVIOR.md CLP-79): the page and entry
 * mapping, the knob nudge and its ends, mark ok, the export word, and the start values (the same as
 * tools/apc_pad_colors.py --pad-h, app/apc40_pad_default.h). With an argument it prints an
 * export for tests/smk_padcal_export_test.py (the round trip into tools/apc_pad_colors.py). */
#include <assert.h>
#include <stdio.h>
#include "app/smk_padcal.h"
#include "app/apc40_lcd565.h"
#include "app/apc40_pad_gamma.h"
#include "app/apc40_pad_default.h"

static smk_padcal_t c;

static void test_mapping(void)
{
    uint8_t p, k, seen[128] = {0};
    for (p = 0; p < SMK_PADCAL_PAGES; p++)
        for (k = 0; k < SMK_PADCAL_PADS; k++) {
            uint8_t e = smk_padcal_entry(p, k);
            assert(e == p * 16u + k && !seen[e]);
            seen[e] = 1u;
        }
    assert(smk_padcal_entry(0, 0) == 0u && smk_padcal_entry(7, 15) == 127u);
    assert(smk_padcal_entry(8, 0) == 0u && smk_padcal_entry(0, 16) == 0u);   /* never out of the table */
    assert(smk_padcal_page_step(0, -1) == 7u && smk_padcal_page_step(7, 1) == 0u);
    assert(smk_padcal_page_step(3, 1) == 4u && smk_padcal_page_step(3, -1) == 2u);
}

static void test_nudge(void)
{
    assert(smk_padcal_nudge(0, -1) == 0u && smk_padcal_nudge(0, -100) == 0u);       /* stops at 0 */
    assert(smk_padcal_nudge(255, 1) == 255u && smk_padcal_nudge(250, 100) == 255u);  /* stops at 255 */
    assert(smk_padcal_nudge(4, 1) == 5u && smk_padcal_nudge(4, -1) == 3u);           /* fine steps when dim */
    assert(smk_padcal_nudge(31, 1) == 32u && smk_padcal_nudge(32, 1) == 34u);
    assert(smk_padcal_nudge(200, -1) == 193u && smk_padcal_nudge(1, -3) == 0u);
}

static void test_start_turn_mark(void)
{
    uint8_t e;
    smk_padcal_start(&c, APC40_LCD565, PAD_GAMMA_LUT, PAD_GAIN_Q8, PAD_FLOOR_LEVEL);
    assert(c.on && c.page == 0u && c.sel == 0u);
    for (e = 0; e < 128u; e++) {
        if (c.rgb[e][0] != APC40_PAD_DEFAULT[e][0] || c.rgb[e][1] != APC40_PAD_DEFAULT[e][1] ||
            c.rgb[e][2] != APC40_PAD_DEFAULT[e][2])
            printf("entry %u: firmware %u,%u,%u, tool %u,%u,%u\n", e, c.rgb[e][0], c.rgb[e][1], c.rgb[e][2],
                   APC40_PAD_DEFAULT[e][0], APC40_PAD_DEFAULT[e][1], APC40_PAD_DEFAULT[e][2]);
        assert(!smk_padcal_is_ok(&c, e));
        assert(smk_padcal_word(&c, e) == ((uint32_t)APC40_PAD_DEFAULT[e][0] | (uint32_t)APC40_PAD_DEFAULT[e][1] << 8 |
                                          (uint32_t)APC40_PAD_DEFAULT[e][2] << 16));
    }
    c.page = 5u;
    c.sel = 1u;                                      /* entry 81 */
    smk_padcal_turn(&c, 2u, -300);                   /* blue to 0, entry ok */
    assert(c.rgb[81][2] == 0u && smk_padcal_is_ok(&c, 81u) && !smk_padcal_is_ok(&c, 80u) && !smk_padcal_is_ok(&c, 82u));
    assert(c.rgb[81][0] == APC40_PAD_DEFAULT[81][0] && c.rgb[81][1] == APC40_PAD_DEFAULT[81][1]);
    smk_padcal_mark(&c);                             /* PLAY: not ok again, the value stays */
    assert(!smk_padcal_is_ok(&c, 81u) && c.rgb[81][2] == 0u);
    smk_padcal_mark(&c);
    assert(smk_padcal_is_ok(&c, 81u));
    assert(smk_padcal_word(&c, 81u) >> 24 == 1u);
    c.page = 7u;
    c.sel = 15u;                                     /* entry 127, the last bit */
    smk_padcal_mark(&c);
    assert(smk_padcal_is_ok(&c, 127u) && c.ok[15] == 0x80u);
}

/* The orientation page (CLP-79): no knob turn + confirm = identity; each correction is one-to-one, and the
 * four corrections of a 2 x 8 grid put the entries where expected. */
static void test_orientation(void)
{
    static const uint8_t TL[4] = {0u, 8u, 7u, 15u};   /* as assumed, rows swapped, rows mirrored, 180 degrees */
    uint8_t t, i;
    smk_padcal_start(&c, APC40_LCD565, PAD_GAMMA_LUT, PAD_GAIN_Q8, PAD_FLOOR_LEVEL);
    assert(c.orient == 1u && c.tl == 0u);
    c.orient = 0u;                                   /* SEQ PLAY with no knob turn */
    for (i = 0; i < 16u; i++)
        assert(smk_padcal_phys(c.tl, i) == i);       /* identity */
    smk_padcal_orient_turn(&c, -1);
    assert(c.tl == 15u);                             /* K2 back from pad 1: wrap to the last pad */
    smk_padcal_orient_turn(&c, 3);
    assert(c.tl == 2u);
    for (t = 0; t < 16u; t++) {
        uint16_t seen = 0u;
        for (i = 0; i < 16u; i++) {
            uint8_t ph = smk_padcal_phys(t, i);
            assert(ph < 16u && smk_padcal_phys(t, ph) == i);   /* the way back (a pad press) */
            seen |= (uint16_t)(1u << ph);
        }
        assert(seen == 0xFFFFu && smk_padcal_phys(t, 0u) == t);   /* one-to-one; position 0 is the chosen pad */
    }
    for (t = 0; t < 4u; t++)
        for (i = 0; i < 16u; i++) {
            uint8_t row = i >> 3, col = i & 7u, ph = smk_padcal_phys(TL[t], i);
            uint8_t er = (TL[t] & 8u) ? 1u - row : row, ec = (TL[t] & 7u) ? 7u - col : col;
            assert(ph == er * 8u + ec);
        }
}

/* A second open of PAD COLOURS (CLP-79): the edits, the ok marks and the orientation correction stay until
 * power off. Only the first open after power-on computes the start values. The orientation page lights the
 * pad of the saved correction. */
static void test_reopen(void)
{
    static smk_padcal_t r;                           /* .bss: as after power-on */
    smk_padcal_start(&r, APC40_LCD565, PAD_GAMMA_LUT, PAD_GAIN_Q8, PAD_FLOOR_LEVEL);
    smk_padcal_orient_turn(&r, 7);                   /* K2: rows mirrored */
    r.orient = 0u;                                   /* SEQ PLAY */
    r.page = 5u;
    r.sel = 1u;                                      /* entry 81 */
    smk_padcal_turn(&r, 0u, 40);                     /* red up, entry ok */
    r.page = 2u;
    r.sel = 3u;                                      /* entry 35 */
    smk_padcal_mark(&r);
    {
        uint8_t keep81[3] = {r.rgb[81][0], r.rgb[81][1], r.rgb[81][2]};
        assert(keep81[0] != APC40_PAD_DEFAULT[81][0]);
        r.on = 0u;                                   /* PATCH: the mode ends */
        smk_padcal_start(&r, APC40_LCD565, PAD_GAMMA_LUT, PAD_GAIN_Q8, PAD_FLOOR_LEVEL);
        assert(r.on == 1u && r.orient == 1u && r.page == 0u && r.sel == 0u);
        assert(r.rgb[81][0] == keep81[0] && r.rgb[81][1] == keep81[1] && r.rgb[81][2] == keep81[2]);
        assert(smk_padcal_is_ok(&r, 81u) && smk_padcal_is_ok(&r, 35u) && !smk_padcal_is_ok(&r, 80u));
        assert(r.tl == 7u && smk_padcal_phys(r.tl, 0u) == 7u);   /* the lit pad: the saved top-left */
        assert(r.rgb[80][0] == APC40_PAD_DEFAULT[80][0] && r.rgb[80][2] == APC40_PAD_DEFAULT[80][2]);
    }
}

/* The ok dot on the LCD (CLP-79) must contrast with its square for every entry. The luminance of an RGB565
 * colour (Rec. 601 weights 77 / 150 / 29 of 256, each channel taken to 8 bits) is 0-255. The limit is 128,
 * half the scale: black on white (or white on black) is 255, and a dot of one fixed colour gives 0 on a
 * square of that colour (entry 3, white). With black on a square of luminance >= 128 and white below it,
 * the difference is never less than 128. */
static uint32_t luma565(uint32_t c)
{
    uint32_t r = (c >> 11 & 31u) * 255u / 31u, g = (c >> 5 & 63u) * 255u / 63u, b = (c & 31u) * 255u / 31u;
    return (77u * r + 150u * g + 29u * b) >> 8;
}
static void test_dot_contrast(void)
{
    uint32_t e, bad = 0u;
    for (e = 0; e < 128u; e++) {
        uint32_t sq = luma565(APC40_LCD565[e]), dot = luma565(smk_padcal_dot565(APC40_LCD565[e]));
        uint32_t diff = sq > dot ? sq - dot : dot - sq;
        if (diff < 128u) {
            if (bad++ < 4u)
                printf("entry %lu: square luminance %lu, dot luminance %lu\n", (unsigned long)e, (unsigned long)sq,
                       (unsigned long)dot);
        }
    }
    if (bad) {
        printf("%lu entries with a dot of low contrast\n", (unsigned long)bad);
        fflush(stdout);
    }
    assert(bad == 0u);
}

int main(int argc, char **argv)
{
    (void)argv;
    test_mapping();
    test_nudge();
    test_orientation();
    test_start_turn_mark();
    test_reopen();
    test_dot_contrast();
    c.tl = 8u;                                       /* the export carries the correction */
    c.on = 0u;                                       /* leave and open again: the export keeps the edits */
    smk_padcal_start(&c, APC40_LCD565, PAD_GAMMA_LUT, PAD_GAIN_Q8, PAD_FLOOR_LEVEL);
    if (argc > 1) {                                  /* the state above, as the INLOG reply words */
        uint8_t e;
        for (e = 0; e < 128u; e++)
            printf("%u %lu\n", e, (unsigned long)smk_padcal_word(&c, e));
        printf("tl %u\n", c.tl);
        return 0;
    }
    printf("smk_padcal_test: ok\n");
    return 0;
}

